import{_ as o,o as i,c as n,j as e,a,a3 as r}from"./chunks/framework.CWCEHGF4.js";const s="/MeshPaintingDoc/quick-start/01-place-mesh.png",l="/MeshPaintingDoc/quick-start/02-add-paint-target.png",c="/MeshPaintingDoc/quick-start/03-runtime-target-settings.png",h="/MeshPaintingDoc/quick-start/04-mesh-targets.png",d="/MeshPaintingDoc/quick-start/05-visibility-collision.png",p="/MeshPaintingDoc/quick-start/06-material-function.png",u="/MeshPaintingDoc/quick-start/07-add-paint-controller.png",m="/MeshPaintingDoc/quick-start/08-control-mode.png",y=JSON.parse('{"title":"Quick Start","description":"","frontmatter":{},"headers":[],"relativePath":"guide/quick-start.md","filePath":"guide/quick-start.md","lastUpdated":1786045981000}'),g={name:"guide/quick-start.md"};function f(k,t,b,P,_,M){return i(),n("div",null,[...t[0]||(t[0]=[e("h1",{id:"quick-start",tabindex:"-1"},[a("Quick Start "),e("a",{class:"header-anchor",href:"#quick-start","aria-label":'Permalink to "Quick Start"'},"​")],-1),e("p",null,"This guide shows the shortest setup for painting a mesh at runtime.",-1),e("h2",{id:"quick-start-tutorial",tabindex:"-1"},[a("Quick Start Tutorial "),e("a",{class:"header-anchor",href:"#quick-start-tutorial","aria-label":'Permalink to "Quick Start Tutorial"'},"​")],-1),e("div",{class:"video-frame"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/aPDALwVkOak",title:"Mesh Painting quick start tutorial video",loading:"lazy",allow:"accelerometer; autoplay; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share",allowfullscreen:""})],-1),r('<h2 id="_1-place-a-mesh-in-the-level" tabindex="-1">1. Place a Mesh in the Level <a class="header-anchor" href="#_1-place-a-mesh-in-the-level" aria-label="Permalink to &quot;1. Place a Mesh in the Level&quot;">​</a></h2><p>Start by placing the mesh you want to paint in your scene.</p><p><img src="'+s+'" alt="A mesh placed in the level"></p><h2 id="_2-add-the-paint-target-component" tabindex="-1">2. Add the Paint Target Component <a class="header-anchor" href="#_2-add-the-paint-target-component" aria-label="Permalink to &quot;2. Add the Paint Target Component&quot;">​</a></h2><p>Select the actor that owns the mesh, then add <code>RuntimeMeshPaintTargetComponent</code> from the Details panel.</p><p>This component owns the runtime render targets, prepares the paint textures, and applies them to the target mesh materials when the game starts.</p><p><img src="'+l+'" alt="RuntimeMeshPaintTargetComponent added to the mesh actor"></p><h2 id="_3-optional-review-the-runtime-target-settings" tabindex="-1">3. Optional: Review the Runtime Target Settings <a class="header-anchor" href="#_3-optional-review-the-runtime-target-settings" aria-label="Permalink to &quot;3. Optional: Review the Runtime Target Settings&quot;">​</a></h2><p>The default render target settings are enough for a first test. You can later adjust the texture resolution, render target format, initial colors, and texture parameter names from the <code>Runtime Target</code> section.</p><p><img src="'+c+'" alt="Runtime target settings"></p><h2 id="_4-optional-choose-mesh-targets-when-needed" tabindex="-1">4. Optional: Choose Mesh Targets When Needed <a class="header-anchor" href="#_4-optional-choose-mesh-targets-when-needed" aria-label="Permalink to &quot;4. Optional: Choose Mesh Targets When Needed&quot;">​</a></h2><p>If the actor has a single mesh component, the target component can resolve it automatically.</p><p>If the actor contains multiple mesh components and you only want specific meshes to be paintable, add their component names to <code>Mesh Targets</code>.</p><p><img src="'+h+'" alt="Mesh Targets list"></p><h2 id="_5-check-collision" tabindex="-1">5. Check Collision <a class="header-anchor" href="#_5-check-collision" aria-label="Permalink to &quot;5. Check Collision&quot;">​</a></h2><p>The mesh must block the trace channel used by the painting controller. By default, this is <code>Visibility</code>.</p><p>If the trace does not hit the mesh, the brush preview cannot lock onto the surface and painting will not be applied.</p><p><img src="'+d+'" alt="Visibility collision set to Block"></p><h2 id="_6-set-up-the-mesh-material" tabindex="-1">6. Set Up the Mesh Material <a class="header-anchor" href="#_6-set-up-the-mesh-material" aria-label="Permalink to &quot;6. Set Up the Mesh Material&quot;">​</a></h2><p>Open the mesh material and set up the <code>Mesh Painting</code> material function correctly.</p><p>For the normal setup, connect <code>BaseColor</code>, <code>Metallic</code>, <code>Roughness</code>, and <code>Brush Emissive</code> to the matching material outputs. <code>Brush Emissive</code> is required for the on-mesh brush area preview.</p><p>For more information about the material setup, see <a href="/MeshPaintingDoc/guide/material-setup">Material Setup</a>.</p><p><img src="'+p+'" alt="Mesh Painting material function connected to a material"></p><h2 id="_7-add-the-painting-controller" tabindex="-1">7. Add the Painting Controller <a class="header-anchor" href="#_7-add-the-painting-controller" aria-label="Permalink to &quot;7. Add the Painting Controller&quot;">​</a></h2><p>Go to the player pawn, character, or controller class that will handle painting input, then add <code>PaintingModeControllerComponent</code>.</p><p>This component handles paint mode input, brush settings, brush preview, color picking, camera behavior, and multiplayer paint command submission.</p><p><img src="'+u+'" alt="PaintingModeControllerComponent added to the player character"></p><h2 id="_8-optional-paint-target-filter" tabindex="-1">8. Optional: Paint Target Filter <a class="header-anchor" href="#_8-optional-paint-target-filter" aria-label="Permalink to &quot;8. Optional: Paint Target Filter&quot;">​</a></h2><p>You can leave <code>PaintTargetComponents</code> empty on the controller. In that case, the controller can paint any valid <code>RuntimeMeshPaintTargetComponent</code> it hits.</p><p>If you fill <code>PaintTargetComponents</code>, painting is limited to only the target components in that list.</p><h2 id="_9-enter-paint-mode" tabindex="-1">9. Enter Paint Mode <a class="header-anchor" href="#_9-enter-paint-mode" aria-label="Permalink to &quot;9. Enter Paint Mode&quot;">​</a></h2><p>Start paint mode with the default toggle input or by calling <code>EnterPaintingMode</code>.</p><p>When setup is correct, the color picker opens, the brush preview follows the mesh surface, and painting applies color to the runtime paint texture.</p><h3 id="optional-control-modes" tabindex="-1">Optional: Control Modes <a class="header-anchor" href="#optional-control-modes" aria-label="Permalink to &quot;Optional: Control Modes&quot;">​</a></h3><p>The controller includes a <code>Control Mode</code> option:</p><ul><li><code>Character Lock</code> locks the normal character look input while paint mode is active and uses the plugin&#39;s painting camera controls.</li><li><code>Simple</code> keeps the setup lighter for custom pawns, drone-style cameras, or cases where you do not want character movement handling from the plugin.</li><li><code>None</code> disables the plugin input handling. Use it only when you want to drive painting manually from your own Blueprint or C++ code.</li></ul><p>If you are using the default First Person template, use <code>Simple</code> mode for the first test. <code>Character Lock</code> expects a character setup with a SpringArm, so <code>EnterPaintingMode</code> can return <code>false</code> on first-person characters that only have a camera.</p><p><img src="'+m+'" alt="Painting controller control mode"></p><h3 id="optional-ready-input-assets" tabindex="-1">Optional: Ready Input Assets <a class="header-anchor" href="#optional-ready-input-assets" aria-label="Permalink to &quot;Optional: Ready Input Assets&quot;">​</a></h3><p>If <code>bLoadDefaultInputAssets</code> is enabled, the component loads the plugin&#39;s ready-to-use input assets:</p><ul><li><code>/MeshPaintingCore/Input/IMC_PaintingMode</code></li><li><code>/MeshPaintingCore/Input/IMC_PaintingModeToggle</code></li></ul><p>Default quick controls:</p><ul><li><code>P</code> toggles paint mode. If <code>bAutoCreateColorPickerWidget</code> is enabled, the color picker menu opens when paint mode starts.</li><li><code>Left Mouse</code> paints under the cursor.</li><li><code>Space</code> picks the color under the cursor.</li><li><code>Middle Mouse + Drag</code> orbits the painting camera.</li><li><code>Shift + Middle Mouse + Drag</code> pans the painting camera.</li><li><code>Ctrl + Mouse Wheel</code> adjusts brush size.</li><li><code>Mouse Wheel</code> zooms the camera in <code>Character Lock</code>.</li><li><code>W/A/S/D</code> moves the character in <code>Character Lock</code>.</li></ul><p>That&#39;s all you need for a basic runtime paint test. If your project needs multiplayer, custom materials, input changes, or advanced brush behavior, continue with the other documentation pages.</p>',44)])])}const w=o(g,[["render",f]]);export{y as __pageData,w as default};
